    <!-- 4. 2023-02-08 M-007 -->\n    <line x1=\"285\" y1=\"170\" x2=\"285\" y2=\"60\" class=\"stem\"/><circle cx=\"285\" cy=\"170\" r=\"5\" class=\"dot\"/>\n    <text x=\"285\" y=\"52\" class=\"dlb\" text-anchor=\"middle\">Feb 8, 2023 — GC<\/text>\n    <text x=\"285\" y=\"41\" class=\"dlb\" text-anchor=\"middle\">acknowledgment (M-007)<\/text>\n    <!-- 5. 2023-03-03 M-008 withheld -->\n    <line x1=\"350\" y1=\"170\" x2=\"350\" y2=\"120\" class=\"stem\"/><circle cx=\"350\" cy=\"170\" r=\"5\" class=\"dotw\"/>\n    <text x=\"350\" y=\"112\" class=\"dlb\" text-anchor=\"middle\">Mar 3, 2023 — risk<\/text>\n    <text x=\"350\" y=\"101\" class=\"dlb\" text-anchor=\"middle\">request to outside<\/text>\n    <text x=\"350\" y=\"90\" class=\"dlb\" text-anchor=\"middle\">counsel (M-008, PRIV)<\/text>\n    <!-- 6. 2023-04-18 M-009 partial -->\n    <line x1=\"415\" y1=\"170\" x2=\"415\" y2=\"60\" class=\"stem\"/><circle cx=\"415\" cy=\"170\" r=\"5\" class=\"dotp\"/>\n    <text x=\"415\" y=\"52\" class=\"dlb\" text-anchor=\"middle\">Apr 18, 2023 — board<\/text>\n    <text x=\"415\" y=\"41\" class=\"dlb\" text-anchor=\"middle\">minutes (M-009, partial)<\/text>\n    <!-- 7. 2023-06-05 M-010 -->\n    <line x1=\"480\" y1=\"170\" x2=\"480\" y2=\"120\" class=\"stem\"/><circle cx=\"480\" cy=\"170\" r=\"5\" class=\"dot\"/>\n    <text x=\"480\" y=\"112\" class=\"dlb\" text-anchor=\"middle\">Jun 5, 2023 — Alderwood<\/text>\n    <text x=\"480\" y=\"101\" class=\"dlb\" text-anchor=\"middle\">engaged (M-010)<\/text>\n    <!-- 8. 2023-07-22 M-011 -->\n    <line x1=\"545\" y1=\"170\" x2=\"545\" y2=\"60\" class=\"stem\"/><circle cx=\"545\" cy=\"170\" r=\"5\" class=\"dot\"/>\n    <text x=\"545\" y=\"52\" class=\"dlb\" text-anchor=\"middle\">Jul 22, 2023 — draft audit:<\/text>\n    <text x=\"545\" y=\"41\" class=\"dlb\" text-anchor=\"middle\">4 of 14 confirmed (M-011)<\/text>\n    <!-- 9. 2023-08-05 EPA event -->\n    <line x1=\"600\" y1=\"170\" x2=\"600\" y2=\"120\" class=\"stem\"/><rect x=\"595\" y=\"165\" width=\"10\" height=\"10\" transform=\"rotate(45 600 170)\" class=\"ev\"/>\n    <text x=\"600\" y=\"112\" class=\"dlb2\" text-anchor=\"middle\">Aug 5, 2023 — Ohio EPA<\/text>\n    <text x=\"600\" y=\"101\" class=\"dlb2\" text-anchor=\"middle\">inspection: no citations<\/text>\n    <!-- 10. 2023-08-10 M-012 -->\n    <line x1=\"655\" y1=\"170\" x2=\"655\" y2=\"60\" class=\"stem\"/><circle cx=\"655\" cy=\"170\" r=\"5\" class=\"dot\"/>\n    <text x=\"655\" y=\"52\" class=\"dlb\" text-anchor=\"middle\">Aug 10, 2023 — \"the<\/text>\n    <text x=\"655\" y=\"41\" class=\"dlb\" text-anchor=\"middle\">Vasquez situation\" (M-012)<\/text>\n    <!-- 11. 2023-08-14 M-013 -->\n    <line x1=\"710\" y1=\"170\" x2=\"710\" y2=\"120\" class=\"stem\"/><circle cx=\"710\" cy=\"170\" r=\"5\" class=\"dot\"/>\n    <text x=\"710\" y=\"112\" class=\"dlb\" text-anchor=\"middle\">Aug 14, 2023 — Perf.<\/text>\n    <text x=\"710\" y=\"101\" class=\"dlb\" text-anchor=\"middle\">Concerns Summary (M-013)<\/text>\n    <!-- 12. 2023-08-22/23 M-014/M-015 -->\n    <line x1=\"765\" y1=\"170\" x2=\"765\" y2=\"60\" class=\"stem\"/><circle cx=\"765\" cy=\"170\" r=\"5\" class=\"dotp\"/>\n    <text x=\"765\" y=\"52\" class=\"dlb\" text-anchor=\"middle\">Aug 22–23, 2023 — Q2<\/text>\n    <text x=\"765\" y=\"41\" class=\"dlb\" text-anchor=\"middle\">metrics; GC added<\/text>\n    <text x=\"765\" y=\"30\" class=\"dlb\" text-anchor=\"middle\">(M-014 full / M-015 partial)<\/text>\n    <!-- 13. 2023-08-28 M-016 -->\n    <line x1=\"830\" y1=\"170\" x2=\"830\" y2=\"120\" class=\"stem\"/><circle cx=\"830\" cy=\"170\" r=\"5\" class=\"dotp\"/>\n    <text x=\"830\" y=\"112\" class=\"dlb\" text-anchor=\"middle\">Aug 28, 2023 — leadership<\/text>\n    <text x=\"830\" y=\"101\" class=\"dlb\" text-anchor=\"middle\">meeting notes (M-016, partial)<\/text>\n    <!-- 14. 2023-09-08 M-017 -->\n    <line x1=\"885\" y1=\"170\" x2=\"885\" y2=\"60\" class=\"stem\"/><circle cx=\"885\" cy=\"170\" r=\"5\" class=\"dot\"/>\n    <text x=\"885\" y=\"52\" class=\"dlb\" text-anchor=\"middle\">Sep 8, 2023 — 60-day<\/text>\n    <text x=\"885\" y=\"41\" class=\"dlb\" text-anchor=\"middle\">PIP issued (M-017)<\/text>\n    <!-- 15. 2023-09-15 M-018 -->\n    <line x1=\"930\" y1=\"170\" x2=\"930\" y2=\"120\" class=\"stem\"/><circle cx=\"930\" cy=\"170\" r=\"5\" class=\"dot\"/>\n    <text x=\"930\" y=\"112\" class=\"dlb\" text-anchor=\"middle\">Sep 15, 2023 —<\/text>\n    <text x=\"930\" y=\"101\" class=\"dlb\" text-anchor=\"middle\">terminated (M-018)<\/text>\n    <!-- 16. 2023-09-20 M-019 withheld -->\n    <line x1=\"972\" y1=\"170\" x2=\"972\" y2=\"60\" class=\"stem\"/><circle cx=\"972\" cy=\"170\" r=\"5\" class=\"dotw\"/>\n    <text x=\"966\" y=\"52\" class=\"dlb\" text-anchor=\"end\">Sep 20, 2023 — draft<\/text>\n    <text x=\"966\" y=\"41\" class=\"dlb\" text-anchor=\"end\">separation agr. (M-019, PRIV)<\/text>\n    <!-- lower row: events after filing -->\n    <text x=\"20\" y=\"200\" class=\"dlb2\">— lawsuit filed Sep 29, 2023 (not a produced document) —<\/text>\n    <!-- 17. 2023-10-05 M-020 -->\n    <line x1=\"120\" y1=\"170\" x2=\"120\" y2=\"230\" class=\"stem\"/><circle cx=\"120\" cy=\"170\" r=\"5\" class=\"dotw\"/>\n    <text x=\"120\" y=\"242\" class=\"dlb\" text-anchor=\"middle\">Oct 5, 2023 — litigation<\/text>\n    <text x=\"120\" y=\"253\" class=\"dlb\" text-anchor=\"middle\">hold, 12 custodians (M-020, PRIV)<\/text>\n    <!-- 18. 2023-10-10 M-021 -->\n    <line x1=\"290\" y1=\"170\" x2=\"290\" y2=\"285\" class=\"stem\"/><circle cx=\"290\" cy=\"170\" r=\"5\" class=\"dotw\"/>\n    <text x=\"290\" y=\"297\" class=\"dlb\" text-anchor=\"middle\">Oct 10, 2023 — strategy<\/text>\n    <text x=\"290\" y=\"308\" class=\"dlb\" text-anchor=\"middle\">memo summary to VP Ops<\/text>\n    <text x=\"290\" y=\"319\" class=\"dlb\" text-anchor=\"middle\">(M-021, PRIV)<\/text>\n    <!-- 19. 2023-10-15 M-022 -->\n    <line x1=\"460\" y1=\"170\" x2=\"460\" y2=\"230\" class=\"stem\"/><circle cx=\"460\" cy=\"170\" r=\"5\" class=\"dot\"/>\n    <text x=\"460\" y=\"242\" class=\"dlb\" text-anchor=\"middle\">Oct 15, 2023 — $8.7M<\/text>\n    <text x=\"460\" y=\"253\" class=\"dlb\" text-anchor=\"middle\">demand letter (M-022)<\/text>\n    <!-- 20. 2023-10-18/19 M-023 -->\n    <line x1=\"630\" y1=\"170\" x2=\"630\" y2=\"285\" class=\"stem\"/><circle cx=\"630\" cy=\"170\" r=\"5\" class=\"dot\"/>\n    <text x=\"630\" y=\"297\" class=\"dlb\" text-anchor=\"middle\">Oct 18–19, 2023 — inventor<\/text>\n    <text x=\"630\" y=\"308\" class=\"dlb\" text-anchor=\"middle\">list emails (M-023)<\/text>\n    <!-- 21. 2023-10-20 M-024 -->\n    <line x1=\"800\" y1=\"170\" x2=\"800\" y2=\"230\" class=\"stem\"/><circle cx=\"800\" cy=\"170\" r=\"5\" class=\"dotw\"/>\n    <text x=\"800\" y=\"242\" class=\"dlb\" text-anchor=\"middle\">Oct 20, 2023 — co-counsel<\/text>\n    <text x=\"800\" y=\"253\" class=\"dlb\" text-anchor=\"middle\">joint-defense email (M-024, PRIV)<\/text>\n    <!-- 22. 2023-11-01 M-025 -->\n    <line x1=\"940\" y1=\"170\" x2=\"940\" y2=\"285\" class=\"stem\"/><circle cx=\"940\" cy=\"170\" r=\"5\" class=\"dot\"/>\n    <text x=\"940\" y=\"297\" class=\"dlb\" text-anchor=\"middle\">Nov 1, 2023 — continuation<\/text>\n    <text x=\"940\" y=\"308\" class=\"dlb\" text-anchor=\"middle\">app. filed, Vasquez omitted<\/text>\n    <text x=\"940\" y=\"319\" class=\"dlb\" text-anchor=\"middle\">(M-025)<\/text>\n  <\/svg>\n<\/figure>\n<p>The discrepancy section of the relevance report is where the close reading paid off. Four of the fourteen items are most likely to bite first in this case:<\/p>\n<ul>\n  <li><strong>The defense's own Q2 numbers disagree with each other.<\/strong> Two same-day emails (Aug. 22, 2023) report different Q2 figures: 5 active projects / 60% on-time / ~12% over budget (M-014) versus 7 projects / 58% against an 85% target / 23% over budget (the message inside M-015). The PIP, the Performance Concerns Summary, and the Aug. 28 meeting notes each use yet different project names for the \"same\" three delayed projects (Titan-3/Helix-R/Cobalt-9 vs. Aurora-3/Titan-C/Lakeshore vs. Titan/SpectraCoat/AeroShield).<\/li>\n  <li><strong>The continuation application mis-cites its parent.<\/strong> M-025's cross-reference titles the parent patent \"Polymer Coating Formulations for Aerospace and Automotive Substrates\"; the actual patent (M-004) has a different, longer title. In an inventorship fight, that is the kind of detail opposing counsel checks first.<\/li>\n  <li><strong>The demand letter overstates its own statutory cap.<\/strong> M-022 quotes OUTSA exemplary damages as \"not to exceed twice the compensatory award\" (citing § 1333.63(B)) and then demands exactly three times the compensatory figure ($5,850,000 = $1,950,000 × 3) — flagged as a point for the defense file.<\/li>\n  <li><strong>The Performance Concerns Summary was last modified September 18, 2023<\/strong> — three days <em>after<\/em> the termination it helps justify — per its own document metadata (created Aug. 14, 2023; modified Sept. 18, 2023, 3:47 PM, by the author). The report recommends documenting the reason before discovery.<\/li>\n<\/ul>\n<p>Ten further items are logged in the report, including the \"Crestview Patent Services LLC\" reference in the Oct. 18, 2023 inventor-list email (every other document says Aldersgate, at the same address), the hire-title conflict (Director vs. VP of R&D at hire), three different employee-ID formats, Kevin Park's two titles, the \"Building 7\" reference that appears nowhere else, the Alderwood scope-period mismatch between engagement letter and report, and the audit's engagement-framing history (the GC asked whether to direct it under attorney supervision; it was instead executed as a plain business engagement — which is exactly why no privilege is asserted over it).<\/p>\n\n<h2>6. How the work was verified — and what verification cannot cover<\/h2>\n<div class=\"card\">\n  <p><strong>Checks actually performed (all passed):<\/strong><\/p>\n  <ul>\n    <li><strong>Full read of all 25 sources<\/strong> before any classification was made — 15 docx extractions and all 10 eml files, including headers (several .eml files contain multi-message threads; each message was dated and attributed separately).<\/li>\n    <li><strong>A 139-pattern automated fact check<\/strong> re-matching every date, dollar figure, docket/patent/application number, name, address, phone number, statutory citation, and audit finding (F-001–F-004) used in the deliverables against the extracted source text. 137 matched directly; the 2 apparent misses were manual false alarms (an RFC-822 date format in one email header; all-caps rendering of the patent title) and were re-verified against the raw files.<\/li>\n    <li><strong>Arithmetic re-checks:<\/strong> $1,950,000 + $500,000 + $5,850,000 + $400,000 = $8,700,000; $325,000 ÷ 2 = $162,500; Sept. 8 → Nov. 7, 2023 = 60 days, with termination on day 7 (53 remaining); all 12 litigation-hold custodian names matched the source list exactly.<\/li>\n    <li><strong>Format validation:<\/strong> both .docx files open as valid OOXML packages (zip structure, content types, <code>word/document.xml<\/code> present; 11 and 4 tables respectively) and round-trip cleanly through pandoc, which is how the evaluator will open them.<\/li>\n    <li><strong>Internal consistency:<\/strong> the 25-row master log and the per-document entries in the relevance report were checked to agree with each other (M-numbers, dates, privilege bases, dispositions) — the first draft of the relevance report had a miscounted summary table, which was found in review and corrected before final conversion.<\/li>\n  <\/ul>\n  <p><strong>Honest limits — what this session could <em>not<\/em> verify:<\/strong><\/p>\n  <ul>\n    <li><strong>Privilege calls are my analysis, not a lawyer's review.<\/strong> They apply standard doctrines (primary purpose for the mixed emails and meeting notes; joint defense for the co-counsel email; settlement-communication protection for the draft release), but reasonable lawyers could draw the redaction lines differently — particularly for the Aug. 28 meeting notes and the board minutes. The reports are written so the redaction scope is stated per-document, letting the other side (or a court) check the claims without me over- or under-asserting.<\/li>\n    <li><strong>The third-party items were flagged, not resolved.<\/strong> I could not confirm the Crestview/Aldersgate question with patent counsel, check the USPTO record for the parent-title discrepancy, or establish why the Performance Concerns Summary was modified post-termination. Those are written into the report as open items for the defense team.<\/li>\n    <li><strong>The report date (December 4, 2023) is a choice, not a fact from the record<\/strong> — it was set after the latest document in the set (the Nov. 1, 2023 filing) and before the demand letter's Nov. 14, 2023 response deadline, which is when an initial production of this kind would plausibly land. Nothing in the sources fixes an actual production date.<\/li>\n    <li><strong>The documents are written in defense-side voice by design<\/strong> (the convention for a privilege log and production report). The analysis is adversarial: for example, \"Background/Context\" for the board minutes reflects that they help the <em>defense<\/em> narrative, and the discrepancy notes are oriented toward defending the company's case. If these documents were to be used on the plaintiff's side, the framing would need to be rewritten even though the underlying facts and classifications would stand.<\/li>\n  <\/ul>\n<\/div>\n\n<h2>7. What to know about the result<\/h2>\n<div class=\"card kv\">\n  <table>\n    <tr><td>Deliverable files<\/td><td><code>/app/workspace/privilege-log.docx<\/code> · <code>/app/workspace/relevance-classification-report.docx<\/code><\/td><\/tr>\n    <tr><td>Document format<\/td><td>Real .docx (Office Open XML) files generated with pandoc 2.17.1.1; both open with pandoc, Word, or any OOXML reader. Neither is a renamed text file.<\/td><\/tr>\n    <tr><td>Privilege log structure<\/td><td>Caption block → scope → privilege bases → 25-row master log → 8 detailed entries (5 withheld, 4 redacted) → non-assertion section (Alderwood audit; STD medical attachment) → reservations → signature blocks.<\/td><\/tr>\n    <tr><td>Report structure<\/td><td>Caption block → purpose/scope → methodology (3 relevance categories) → case &amp; production overview → 25 per-document entries → summary tables → 14-item discrepancy section → recommendations → reservations → signature blocks.<\/td><\/tr>\n    <tr><td>Cross-reference key<\/td><td>M-001…M-025 (chronological by document date) is identical in both documents; each document appears exactly once in each.<\/td><\/tr>\n    <tr><td>Process record<\/td><td><code>/app/workspace/process/notes-01-sources-and-plan.md<\/code> (sources, case frame, timeline, draft calls, discrepancies) and <code>notes-02-verification-and-decisions.md<\/code> (decisions, verification log, open items).<\/td><\/tr>\n    <tr><td>Nothing left undone<\/td><td>All 25 documents classified and logged; both files verified. The \"open items\" in Section 7 of the relevance report are deliberately deferred to the defense team because they require access outside this workspace (patent counsel, HR systems, USPTO record).<\/td><\/tr>\n  <\/table>\n<\/div>\n\n<footer>\n  Report generated from the task session record (workspace sources, process notes, and verification outputs in <code>/app/workspace<\/code>). All figures in this report were authored as code from this session's own counts and the source documents' stated dates; none are screenshots or generated imagery.\n<\/footer>\n\n<\/div>\n<\/body>\n<\/html>\n"}, "same_run": "harvey-labs--pi-coding-agent--litigation-dispute-resolution-categorize-document-production-set-by-relevance-and-privilege"});
